# Python solution for the nth delannoy number
def dealnnoy_num(m, n):
    # The formula for the nth delannoy number is (n choose m)^2 - C(n+m, m)
    # where C(n, m) is the binomial coefficient, which can be calculated as n!/(m!(n-m)!)
    def binomial_coefficient(n, m):
        if m > n:
            m, n = n, m
        num = 1
        for i in range(n - m - 1):
            num *= (n - i)
            num //= (i + 1)
        return num

    return binomial_coefficient(n, m)**2 - binomial_coefficient(n + m, m)
```

