def nth_super_ugly_number(n, primes):
    heap = [1]
    used = set([1])
    for i in range(1, n):
        minValue = heapq.heappop(heap)
        for p in primes:
            newUgly = minValue * p
            if newUgly not in used:
                used.add(newUgly)
                heapq.heappush(heap, newUgly)
    return heapq.heappop(heap)
