def coin_change(coins, change, count):
    # Base case: if no coins left and change is zero, return 1
    if len(coins) == 0 and change == 0:
        return 1
    # Base case: if change is zero but coins left, return 0
    elif change == 0:
        return 0
    # If no coins left and change is not zero, return 0
    elif len(coins) == 0:
        return 0
    # If the last coin is larger than the change, skip it
    elif coins[len(coins) - 1] > change:
        return coin_change(coins[:-1], change, count)
    # If the last coin is equal to the change, count it and go to the next coin
    elif coins[len(coins) - 1] == change:
        return coin_change(coins[:-1], change - coins[len(coins) - 1], count + 1)
    # If the last coin is less than the change, count it and continue trying with the same coin
    else:
        return coin_change(coins, change - coins[len(coins) - 1], count) + coin_change(coins[:-1], change, count)
