        return 0
    if len(coins) == 0:
        return float('inf')
    if amount < 0:
        return float('inf')
    if cached[amount] != None:
        return cached[amount]
    result = min(coin_change(coins, amount - coins[0],cached) + 1, coin_change(coins[1:], amount, cached))
    cached[amount] = result
    return result
