import numpy as np

def min_Jumps(h, w, d):
    # Set up the distance matrix for each step
    dist = np.zeros((h, w))
    for i in range(h):
        for j in range(w):
            if (i, j) == (d, 0):
                dist[i, j] = 0
            elif (i, j) == (0, 0):
                dist[i, j] = None
            elif i > 0:
                dist[i, j] = min(dist[i-1, j], dist[i, j]) + 1
            if j > 0:
                dist[i, j] = min(dist[i, j], dist[i, j-1]) + 1
    return dist[h-1, w-1]
