def find_Max(arr, low, high):
    # Base case
    if high < low:
        return arr[low]
    if high == low:
        return arr[low]

    mid = (low + high) // 2

    # If the array is rotated, then the first half will have elements smaller than the last half
    if arr[mid] > arr[high]:
        # It means the maximum element is in the right half
        return find_Max(arr, mid + 1, high)
    else:
        # It means the maximum element is in the left half
        return find_Max(arr, low, mid - 1)
