def find_Max(seq, start, end):
    # Checking if the sequence is already sorted
    if seq[start] <= seq[end]:
        return seq[end]
    # Finding the midpoint of the sequence
    mid = (start + end) // 2
    # If the element at the midpoint is greater than the last element, continue searching in the right part
    if seq[mid] > seq[end]:
        return find_Max(seq, mid + 1, end)
    # Otherwise, continue searching in the left part
    return find_Max(seq, start, mid)
