def find_Max(arr, left, right):
    if right >= left:
        mid = left + (right - left) // 2
        # Check if mid is a peak element
        if (mid == 0 or arr[mid] >= arr[mid-1]) and (mid == len(arr)-1 or arr[mid] >= arr[mid+1]):
            return arr[mid]
        # If the middle element is less than the last element, the maximum must be on the right side
        elif arr[mid] < arr[right]:
            return find_Max(arr, left, mid-1)
        else:
            # The maximum must be on the left side
            return find_Max(arr, mid+1, right)
    return None
