def check_date(day, month, year):
    # Check if the year is leap year
    if ((year % 4 == 0 and year % 100 != 0) or (year % 400 == 0)):
        leap_year = True
    else:
        leap_year = False

    # Check if the month contains 30 or 31 days
    if (month == 4 or month == 6 or month == 9 or month == 11):
        if (day <= 30):
            return True
        else:
            return False
    elif (month == 2):
        # Check if the year is a leap year to determine the number of days
        if (leap_year == True):
            if (day <= 29):
                return True
            else:
                return False
        else:
            if (day <= 28):
                return True
            else:
                return False
    else:
        return False
