def find_Min_Sum(n):
    def factor_sum factor(n):
        count = 0
        for i in range(1, int(n**0.5) + 1):
            if n % i == 0:
                count += i + n // i
                if i != n // i:  # Avoid adding the square root twice for perfect squares
                    count += i * (n // i)
        return count

    min_sum = sum(factor_sum(factor(i)) for i in range(1, n + 1))
    return min_sum
```

