def max_product(arr):
    if len(arr) < 2:
        return None  # Not enough numbers to form a product pair

    # Initialize the first two elements as the highest and lowest product found
    max1, max2 = max(arr[0], arr[1]), min(arr[0], arr[1])

    # Iterate through the array starting from the third element
    for i in range(2, len(arr)):
        if arr[i] > max1:
            # If the current element is greater than both max1 and max2
            max2, max1 = max1, arr[i]
        elif arr[i] > max2:
            # If the current element is only greater than max2, update max2
            max2 = arr[i]

    # Return the pair of products
    return (max1, max2)
