    def sum_to_h(n, h):
        return sum(i * h for i in range(1, n+1))

    # Find the greatest common divisor (GCD) of the first n numbers
    def find_gcd(n):
        return reduce(gcd, range(1, n+1))

    # Iterate up from the sum of the first n natural numbers to find the smallest_multiple
    h = n * sum(range(1, n+1)) // find_gcd(n)
    while True:
        if sum_to_h(n, h) == sum(range(1, n+1)):
            return h
        h += n

