def find_kth(arr1, arr2, k1, k2, n1, n2):
    # Initialize pointers for both arrays
    i, j = k1 - 1, k2 - 1

    while i < n1 and j < n2:
        if arr1[i] < arr2[j]:
            i += 1
        else:
            j += 1

    # If i points to the end of arr1 but not j, return the next element from arr2
    if i == n1:
        return arr2[j]

    # If j points to the end of arr2 but not i, return the next element from arr1
    if j == n2:
        return arr1[i]

    # If i or j is out of bounds, return the minimum of the remaining elements
    if i >= n1:
        return arr2[j]
    elif j >= n2:
        return arr1[i]

    # Otherwise, return the element at the current pointers
    else:
        return min(arr1[i], arr2[j])
