            num += 1
        top += 1

        for i in range(top, bottom + 1):
            result[i][right] = num
            num += 1
        right -= 1

        if top <= bottom:
            for i in range(right, left - 1, -1):
                result[bottom][i] = num
                num += 1
            bottom -= 1

        if left <= right:
            for i in range(bottom, top - 1, -1):
                result[i][left] = num
                num += 1
            left += 1

    return result
```

