import re
def n_common_words(text, n):
    # Split the text into words using regular expression
    words = re.findall(r'\b\w+\b', text.lower())
    # Count occurrences of each word
    word_count = {}
    for word in words:
        if word in word_count:
            word_count[word] += 1
        else:
            word_count[word] = 1
    # Get the n most common words
    most_common = sorted(word_count.items(), key=lambda item: item[1], reverse=True)[:n]
    return most_common
```

