import numpy as np

def lcs_of_three(str1, str2, str3, m, n, p):
    # Create a 3D array to store lengths of LCSs
    dp = np.zeros((m+1, n+1, p+1))

    # Build the dp array in bottom-up manner
    for i in range(1, m+1):
        for j in range(1, n+1):
            for k in range(1, p+1):
                if str1[i-1] == str2[j-1] == str3[k-1]:
                    dp[i][j][k] = 1 + dp[i-1][j-1][k-1]
                else:
                    dp[i][j][k] = max(dp[i-1][j][k], dp[i][j-1][k], dp[i][j][k-1])

    # The length of the longest common subsequence is at dp[m][n][p]
    return int(dp[m][n][p])

