def lcs_of_three(s1, s2, s3, m, n, l):
    # Initialize a 3D list to store the lengths of LCS of substring pairs
    dp = [[[0 for _ in range(l)] for _ in range(n)] for _ in range(m)]

    # Fill the dp matrix for all possible lengths
    for i in range(m):
        for j in range(n):
            for k in range(l):
                # If characters match, add 1 to the previous diagonal
                if s1[i-1] == s2[j-1] == s3[k-1]:
                    dp[i][j][k] = dp[i-1][j-1][k-1] + 1
                else:
                    # Choose the maximum length from the previous cells
                    dp[i][j][k] = max(dp[i-1][j][k], dp[i][j-1][k], dp[i][j][k-1])

    # The result is the value in the bottom-right cell
    return dp[m][n][l]
