def max_char(s):
    # Initialize an empty dictionary to store the characters and their counts
    char_count = {}

    # Iterate through each character in the string
    for char in s:
        if char in char_count:
            # If the character is already in the dictionary, increment its count
            char_count[char] += 1
        else:
            # If the character is not in the dictionary, add it with a count of 1
            char_count[char] = 1

    # Initialize variables to keep track of the most common character and its count
    max_char = None
    max_count = 0

    # Iterate through the dictionary to find the character with the highest count
    for char, count in char_count.items():
        if count > max_count:
            max_char = char
            max_count = count

    # Return the most common character
    return max_char
