def find_Min_Swaps(arr, n):
    swap_operations = 0
    for i in range(n-1):
        if arr[i] > arr[i+1]:
            # Find the smallest element in the subarray from the indices after the current one
            min_idx = i + 1
            for j in range(i+2, n):
                if arr[j] < arr[min_idx]:
                    min_idx = j
            # Swap the current element with the smallest element found
            arr[i], arr[min_idx] = arr[min_idx], arr[i]
            swap_operations += 1
    return swap_operations
```

