def most_common_elem(text, n):
    # Dictionary to store the count of each character
    char_count = {}

    # Count the occurrences of each character
    for char in text:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Sort characters by count in descending order
    sorted_char_count = sorted(char_count.items(), key=lambda x: x[1], reverse=True)

    # Return the n most common characters and their counts
    return sorted_char_count[:n]
