        if str1[i] != str2[i]:
            # Find the correct position for the current bit in str1
            for j in range(i + 1, n):
                if str1[j] == str2[i]:
                    # Swap the current bit with the correct position bit
                    str1[i], str1[j] = str1[j], str1[i]
