def min_Swaps(s1, s2):
    n = len(s1) 
    x = y = 0
    swap = 0
    for i in range(n):
        if s1[i] != s2[i]:
            if s1[i] == '0':
                x += 1
            else:
                y += 1
    while x < y:
        if s2[x] == '1':
            x += 1
            swap += 1
        elif s1[y] == '0':
            s1[y], s1[x] = s1[x], s1[y]
            swap += 1
        y -= 1
    return swap
