```python
def check_min_heap(arr, i):
    n = len(arr)
    while i * 2 + 1 < n:
        left = i * 2 + 1
        right = i * 2 + 2
        smallest = i

        if (arr[left] < arr[smallest] and left < n):
            smallest = left

        if (arr[right] < arr[smallest] and right < n):
            smallest = right

        if smallest != i:
            arr[i], arr[smallest] = arr[smallest], arr[i]
            i = smallest
        else:
            break
    return True

print(check_min_heap([1, 2, 3, 4, 5, 6], 0))  # Returns True
