import math

def calculate-parent(index):
    # Calculate the parent parent of node at the given index
    return math.floor((index - 1) / 2)

def check_min_heap(heap, index):
    left_index = calculate_parent(index)
    right_index = calculate_parent(index) + 1

    # If the current index is not a leaf
    if left_index >= len(heap) and right_index >= len(heap):
        return True

    # Check if the parent is smaller than its child intervals
    if left_index < len(heap) and heap[left_index] > heap[index]:
        return False
    if right_index < len(heap) and heap[right_index] > heap[index]:
        return False

    # Recursively check for the child intervals
    return check_min_heap(heap, left_index) and check_min_heap(heap, right_index)

# Test the function
print(check_min_heap([1, 2, 3, 4, 5, 6], 0))  # Output: True
```

