import math

def rgb_to_hsv(r, g, b):
    r, g, b = r / 255.0, g / 255.0, b / 255.0
    mx, mn = max(r, g, b), min(r, g, b)
    d = mx - mn
    if mx == mn:
        h = 0
    elif mx == r:
        h = (60 * ((g - b) / d) + 360) % 360
    elif mx == g:
        h = (60 * ((b - r) / d) + 120) % 360
    elif mx == b:
        h = (60 * ((r - g) / d) + 240) % 360
    if mx == 0:
        s = 0
    else:
        s = d / mx
    v = mx
    return h, s, v
