def rgb_to_hsv(r, g, b):
    r, g, b = r / 255.0, g / 255.0, b / 255.0
    max_color = max(r, g, b)
    min_color = min(r, g, b)
    delta = max_color - min_color
    if delta == 0.0: 
        h = 0
        s = 0
    else: 
        if max_color == r: 
            h = (60.0 * ((g - b) / delta) + 360.0) % 360.0
        elif max_color == g: 
            h = (60.0 * ((b - r) / delta) + 120.0) % 360.0
        else: 
            h = (60.0 * ((r - g) / delta) + 240.0) % 360.0
        s = delta / max_color
    v = max_color * 100
    return (h, s, v)

