def min_cost(cost, m, n):
    l = [[0]*n for i in range(m)]
    l[0][0] = cost[0][0]
    for i in range(m):
        for j in range(n):
            if i == 0 and j == 0:
                continue
            x, y = abs(i-1), abs(j-1)
            l[i][j] = cost[i][j] + min(l[x][y], l[i][j-x], l[i-y][y])
    return l[m-1][n-1]
