    count = {}
    # Calculate frequency of each element in array
    for i in range(n):
        if arr[i] in count:
            count[arr[i]] += 1
        else:
            count[arr[i]] = 1
    # Initialize min and max frequency with first element frequency
    min_freq = max_freq = count[arr[0]]
    # Iterate through count map to find min and max frequency
    for freq in count.values():
        if freq < min_freq:
            min_freq = freq
        elif freq > max_freq:
            max_freq = freq
    # Return difference between MAX and MIN frequency
