def modular_sum(arr, n, m):
    if n == 0:
        return False

    # Create a 2D matrix to store results of subproblems
    T = [[False for _ in range(m+1)] for _ in range(n+1)]

    # Initialize the first row, value is False because only zeroth sum has one way, i.e., empty set
    for i in range(n+1):
        T[i][0] = True

    # Fill the T[][] in bottom up manner
    for i in range(1, n+1):
        for j in range(1, m+1):
            if arr[i-1] <= j:
                T[i][j] = T[i-1][j] or T[i-1][j-arr[i-1]]
            else:
                T[i][j] = T[i-1][j]

    return T[n][m]
```

