def min_coins(coins, amount, n):
    dp = [float('inf')] * (amount + 1)
    dp[0] = 0

    for i in range(1, n + 1):
        for j in range(1, amount + 1):
            if j >= coins[i - 1]:
                dp[j] = min(dp[j], dp[j - coins[i - 1]] + 1)

    return dp[amount]
