def get_pairs_count(numbers, target_sum, pair_count):
    # Dictionary to store numbers and their occurrences
    num_count = {}

    # Iterate over each number in the array
    for num in numbers:
        # Calculate the required number to reach the target sum
        req_num = target_sum - num

        # Check if the required number is already in the dictionary
        if req_num in num_count:
            pair_count += num_count[req_num]

        # Update the count of the current number
        if num in num_count:
            num_count[num] += 1
        else:
            num_count[num] = 1

    return pair_count
```

