def check(arr, n):
    # Check if the first element is less than the last element
    if arr[0] < arr[-1]:
        # If true, check if the array can be sorted by picking the first element
        for i in range(1, n//2 + 1):
            if arr[i] > arr[i-1]:
                return False
            elif arr[n-i] < arr[n-i+1]:
                return False
        return True
    else:
        # If the first element is greater than or equal to the last element
        # Check if the array can be sorted by picking the last element
        for i in range(n-1, n//2 - 1, -1):
            if arr[i] < arr[i-1]:
                return False
            elif arr[0] > arr[1]:
                return False
        return True
```

