def find_longest_conseq_subseq(arr, n):
    count = 1
    max_count = 1
    for i in range(1, n):
        if arr[i] == arr[i-1] + 1:
            count += 1
            max_count = max(count, max_count)
        else:
            count = 1
    return max_count
