from typing import List

def find_longest_conseq_subseq(arr: List[int], n: int) -> int:
    # Dictionary to store the count of values from 0 to max(arr)
    freqMap = {
        x: 0 for x in range(max(arr) + 1)
    }

    # Update frequency count for each element
    for i in range(n):
        freqMap[arr[i]] += 1

    # Track the length of the longest sequence
    longestSeq = 0

    # Check for each value if it's the beginning of a sequence
    for i in range(n):
        if freqMap[arr[i]] > 0:

            # Count the length of the sequence
            length = 1
            for j in range(arr[i] + 1, max(arr) + 1):
                if freqMap[j] > 0:
                    length += 1
                else:
                    break

            # Update the longest sequence length
            longestSeq = max(longestSeq, length)

    return longestSeq
