def max_sum_increasing_subsequence(arr, n):
    if n <= 0:
        return 0
    dp = [arr[i] for i in range(n)]  # Initialize dp array to arr elements itself
    max_sum = dp[0]  # Initialize max_sum with the initial element

    for i in range(1, n):
        for j in range(i):
            if arr[i] > arr[j] and dp[i] < dp[j] + arr[i]:
                dp[i] = dp[j] + arr[i]  # Update dp[i]
