def generate_matrix(n):
    m, n = n, n
    t, b, l, r = 0, m-1, 0, n-1
    arr = [[0 for _ in range(n)] for _ in range(m)]

    num = 1
    while num <= m*n:
        if t <= b:
            for i in range(l, r+1):
                arr[t][i] = num
                num += 1
            t += 1
        if l <= r:
            for i in range(t, b+1):
                arr[i][r] = num
                num += 1
            r -= 1
        if t <= b:
            for i in range(r, l-1, -1):
                arr[b][i] = num
                num += 1
            b -= 1
        if l <= r:
            for i in range(b, t-1, -1):
                arr[i][l] = num
                num += 1
            l += 1

    return arr
