import heapq

def maximum_product(lst):
    max_heap = []
    min_heap = []

    # Convert list to numpy array
    arr = np.array(lst)

    # Add elements of array to max heap
    for num in arr:
        if len(max_heap) < 3:
            heapq.heappush(max_heap, num)
        else:
            if num > max_heap[0]:
                heapq.heappop(max_heap)
                heapq.heappush(max_heap, num)

    # Convert max heap to list and calculate product of largest 3 numbers
    max_prod = 1
    for num in sorted(max_heap, reverse=True):
        max_prod *= num

    # Add elements of array to min heap
    for num in arr:
        if len(min_heap) < 3:
            heapq.heappush(min_heap, num)
        else:
            if num < min_heap[0]:
                heapq.heappop(min_heap)
                heapq.heappush(min_heap, num)

    # Convert min heap to list and calculate product of smallest 3 numbers
    min_prod = 1
    for num in sorted(min_heap):
        min_prod *= num

    # Return the maximum product of the three numbers
    return max(max_prod, min_prod)
