from typing import List, Tuple

class Pair:
    def __init__(self, start, end):
        self.start = start
        self.end = end

    def __repr__(self):
        return f"Pair({self.start}, {self.end})"

def max_chain_length(pairs: List[Pair], n: int) -> int:
    pairs.sort(key=lambda x: x.end)

    m = [1] * n
    for i in range(1, n):
        for j in range(i):
            if pairs[j].end < pairs[i].start and m[i] < m[j] + 1:
                m[i] = m[j] + 1

    return max(m)
```

In this solution, we first define a `Pair` class to represent each pair of lengths by its start and end values. We then sort the list of `Pair` objects based on their end values. Next, we initialize a list `m` where each element `m[i]` is set to 1, indicating that the longest chain ending at `pair[i]` starts by itself. We iterate through each `pair[i]` and compare it with all previous `pair[j]` where `pair[j].end < pair[i].start`. If such a pair is found, we update `m[i]` to be the maximum of its current value and `m[j] + 1`. Finally, the function returns the maximum value in the `m` list, which represents the length of the longest chain that can be formed from the given set of pairs.

```python
class Pair:
    def __init__(self, first, second):
        self.first = first
        self.second = second

def max_chain_length(pairs, n):
    sorted_pairs = sorted(pairs, key=lambda x: x.second)
    LIS = [1] * n
    for i in range(1, n):
        for j in range(i):
            if sorted_pairs[i].first > sorted_pairs[j].second and LIS[i] < LIS[j] + 1:
                LIS[i] = LIS[j] + 1
    return max(LIS)

