from typing import List, Tuple

class Pair:
    def __init__(self, first: int, second: int):
        self.first = first
        self.second = second

    def __lt__(self, other: 'Pair') -> bool:
        return self.first < other.first

def max_chain_length(pairs: List[Pair], n: int) -> int:
    sorted_pairs = sorted(pairs)
    dp = [1] * n

    for i in range(1, n):
        for j in range(i):
            if sorted_pairs[i].first > sorted_pairs[j].second:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

# Test the function
