def dealnnoy_num(n, k):
    # Base case: dealnnoy_num(0, 0) and dealnnoy_num(n, 0) should both be 1
    if n == 0:
        return 1
    # Initialize the dp table
    dp = [[0 for j in range(k+1)] for i in range(n+1)]
    # Base cases for the dp table
    for i in range(n+1):
        dp[i][0] = 1
    for i in range(n+1):
        dp[0][i] = 1
    # Fill the dp table
    for i in range(1, n+1):
        for j in range(1, k+1):
            dp[i][j] = dp[i-1][j-1] + dp[i-2][j]
    # Return the value at the last ordered pair index
    return dp[n][k]
