    dp = [[0 for _ in range(k + 1)] for _ in range(n + 1)]

    # Base cases
    for i in range(n + 1):
        dp[i][0] = 1  # There's one way to choose an empty combination for any n
    for j in range(k + 1):
        dp[0][j] = 0  # There are no ways to choose elements for any n with 0 from k

    # Fill the dp array using the recurrence relation
    for i in range(1, n + 1):
        for j in range(1, k + 1):
            if j < i:
                dp[i][j] = dp[i][j - 1]  # Cannot use any from set of index less than i
            else:
                dp[i][j] = dp[i][j - 1] + dp[i - 1][j - 1]  # Use i previous elements and remaining from k - i previous elements

    # The nth delannoy number is stored in dp[n][k]
    return dp[n][k]
