from collections import Counter, defaultdict
def unique_sublists(lst):
    # Use a defaultdict to count the frequency of each sublist
    sublist_freq = defaultdict(int)
    for sublist in lst:
        sublist_freq[tuple(sublist)] += 1

    # Filter out the sublists that appear exactly once
    unique_sublists = {key: freq for key, freq in sublist_freq.items() if freq == 1}

    # Group the unique sublists by their frequency and count
    result = {}
    for freq, sublists in sorted(unique_sublists.items()):
        result[freq] = len(sublists)

    return result
