def longest_increasing_subsequence(arr):
    # Initialize the lengths array with 1s, as each element is an increasing subsequence of length 1
    lengths = [1] * len(arr)

    # Iterate over the array starting from the second element
    for i in range(1, len(arr)):
        # For each element, check all previous elements
        for j in range(i):
            # If the current element is greater than the previous element, update the length
            if arr[i] > arr[j] and lengths[i] < lengths[j] + 1:
                lengths[i] = lengths[j] + 1

    # The maximum value in the lengths array is the length of the longest increasing subsequence
    return max(lengths)
